    'ENT_' || LEFT(MD5('CCN' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN_NO"), '[^0-9A-Za-z]', ''))) = 0 OR LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN_NO"), '[^0-9A-Za-z]', ''))) > 6 OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN_NO"), '[^0-9A-Za-z]', '')), 6, '0') = REPEAT('0', 6) THEN NULL ELSE LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN_NO"), '[^0-9A-Za-z]', '')), 6, '0') END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

